import React, { useState, useEffect, useRef, useCallback } from 'react';
import * as pdfjsLib from 'pdfjs-dist';
import { motion, AnimatePresence } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import { useSwipeable } from 'react-swipeable';

// Set up PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

const PDFViewer = ({ pdfPath, fileUrl, bookTitle }) => {
  const { theme } = useTheme();
  const [pdf, setPdf] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [scale, setScale] = useState(1.2);
  const [error, setError] = useState(null);
  const [pageDirection, setPageDirection] = useState(0);
  const [pageUrls, setPageUrls] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [showPlaceholder, setShowPlaceholder] = useState(false);
  const [showDebug, setShowDebug] = useState(false);
  const [debugInfo, setDebugInfo] = useState({});
  const containerRef = useRef(null);
  
  // Use either pdfPath or fileUrl 
  const effectivePath = pdfPath || fileUrl;
  
  // Function to render a page to the cache
  const renderPageToCache = async (pdfDoc, pageNum, cache) => {
    if (!pdfDoc) return null;
    
    try {
      const page = await pdfDoc.getPage(pageNum);
      const viewport = page.getViewport({ scale: 1.0 });
      
      // Create an offscreen canvas
      const canvas = document.createElement('canvas');
      canvas.height = viewport.height;
      canvas.width = viewport.width;
      
      // Render to the canvas
      const renderContext = {
        canvasContext: canvas.getContext('2d'),
        viewport: viewport
      };
      
      await page.render(renderContext).promise;
      
      // Store the rendered page as a data URL
      const pageUrl = canvas.toDataURL('image/png');
      cache[pageNum] = pageUrl;
      
      return pageUrl;
    } catch (err) {
      console.error(`Error rendering page ${pageNum}:`, err);
      return null;
    }
  };
  
  // Change page function wrapped in useCallback to prevent re-creation on every render
  const changePage = useCallback((delta) => {
    if (!pdf) return;
    
    // Make sure we stay within bounds
    const newPage = Math.max(1, Math.min(currentPage + delta, totalPages));
    
    // If already at the target page, do nothing
    if (newPage === currentPage) return;
    
    // Set the direction for animation
    setPageDirection(delta > 0 ? 1 : -1);
    
    // Change page
    setCurrentPage(newPage);
  }, [currentPage, pdf, totalPages]);
  
  // Change zoom level
  const changeZoom = (delta) => {
    const newScale = Math.max(0.5, Math.min(scale + delta, 3));
    setScale(newScale);
  };
  
  // Page flip animation variants
  const pageVariants = {
    enter: (direction) => ({
      x: direction > 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction > 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    }),
    center: {
      x: 0,
      opacity: 1,
      rotateY: 0,
      boxShadow: "0px 10px 30px rgba(0, 0, 0, 0.3)"
    },
    exit: (direction) => ({
      x: direction < 0 ? "100%" : "-100%",
      opacity: 0,
      rotateY: direction < 0 ? -20 : 20,
      boxShadow: "0px 0px 0px rgba(0, 0, 0, 0.2)"
    })
  };
  
  // Handle swipe gestures
  const swipeHandlers = useSwipeable({
    onSwipedLeft: () => changePage(1),
    onSwipedRight: () => changePage(-1),
    preventDefaultTouchmoveEvent: true,
    trackMouse: false,
    trackTouch: true,
    delta: 10, // Lower threshold for swipe detection
    swipeDuration: 500, // Allow slower swipes
  });

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'ArrowRight') {
        changePage(1);
      } else if (e.key === 'ArrowLeft') {
        changePage(-1);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [changePage]);
  
  // Resize handling for responsiveness
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        const containerWidth = containerRef.current.clientWidth;
        const containerHeight = containerRef.current.clientHeight;
        // More responsive scaling based on both dimensions
        const isMobile = window.innerWidth < 768;
        // Use smaller scale on mobile for better fit
        const newScale = isMobile 
          ? Math.min(0.9, (containerWidth / 600) * 0.9, (containerHeight / 800) * 0.9) 
          : Math.min(1.2, containerWidth / 600);
        setScale(newScale);
      }
    };
    
    handleResize(); // Call once to initialize
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Add touch gesture handling for pinch zoom
  useEffect(() => {
    if (!containerRef.current) return;
    
    let initialDistance = 0;
    let initialScale = scale;
    
    const handleTouchStart = (e) => {
      if (e.touches.length === 2) {
        // Get initial distance between two fingers
        initialDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        initialScale = scale;
      }
    };
    
    const handleTouchMove = (e) => {
      if (e.touches.length === 2) {
        // Calculate new distance
        const newDistance = Math.hypot(
          e.touches[0].clientX - e.touches[1].clientX,
          e.touches[0].clientY - e.touches[1].clientY
        );
        
        // Calculate scale factor based on distance change
        const scaleFactor = newDistance / initialDistance;
        const newScale = Math.max(0.5, Math.min(3, initialScale * scaleFactor));
        
        setScale(newScale);
        e.preventDefault(); // Prevent default pinch zoom
      }
    };
    
    const container = containerRef.current;
    container.addEventListener('touchstart', handleTouchStart, { passive: false });
    container.addEventListener('touchmove', handleTouchMove, { passive: false });
    
    return () => {
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);
    };
  }, [scale]);

  // Update the document title with the book title
  useEffect(() => {
    if (bookTitle) {
      document.title = `Reading: ${bookTitle}`;
      
      return () => {
        document.title = 'Track Your Study';
      };
    }
  }, [bookTitle]);

  // Load the PDF document - simplified version without URL fixing
  useEffect(() => {
    let loadingTask = null;
    let isMounted = true;
    let abortController = new AbortController();
    
    async function loadPDF() {
      try {
        setError(null);
        setIsLoading(true);
        setShowPlaceholder(false);
        
        // Handle case when effectivePath is not provided
        if (!effectivePath) {
          if (isMounted) {
            setShowPlaceholder(true);
            setError("No PDF document specified");
            setIsLoading(false);
          }
          return;
        }
        
        console.log("Loading PDF from path:", effectivePath);
        
        // Load the PDF document directly with minimal options
        loadingTask = pdfjsLib.getDocument({
          url: effectivePath,
          // Use minimal options to reduce potential issues
          cMapUrl: 'https://cdn.jsdelivr.net/npm/pdfjs-dist@2.16.105/cmaps/',
          cMapPacked: true
        });
        
        // Track loading progress
        loadingTask.onProgress = (progress) => {
          if (isMounted) {
            const percent = Math.round(progress.loaded / (progress.total || 1) * 100);
            console.log(`PDF loading progress: ${percent}%`);
          }
        };
        
        const loadedPdf = await loadingTask.promise;
        console.log("PDF loaded successfully with", loadedPdf.numPages, "pages");
        
        if (!isMounted) return;
        
        setPdf(loadedPdf);
        setTotalPages(loadedPdf.numPages);
        setCurrentPage(1);
        
        // Pre-render first page
        if (loadedPdf.numPages > 0) {
          const pageCache = {};
          
          try {
            const page1Url = await renderPageToCache(loadedPdf, 1, pageCache);
            console.log("First page rendered:", !!page1Url);
            
            if (isMounted) {
              setPageUrls(pageCache);
              setIsLoading(false);
            }
          } catch (err) {
            console.error("Error rendering page:", err);
            if (isMounted) {
              setError("Error rendering PDF page: " + err.message);
              setIsLoading(false);
            }
          }
        } else {
          setIsLoading(false);
          setError("PDF has no pages");
        }
      } catch (err) {
        if (isMounted) {
          console.error('Error loading PDF:', err);
          setError(`PDF could not be loaded: ${err.message}`);
          setIsLoading(false);
        }
      }
    }
    
    loadPDF();
    
    return () => {
      isMounted = false;
      abortController.abort();
      
      if (loadingTask && loadingTask.destroy) {
        try {
          loadingTask.destroy();
        } catch (err) {
          console.error('Error destroying PDF task:', err);
        }
      }
    };
  }, [effectivePath]);
  
  // Preload the next page when needed
  useEffect(() => {
    if (!pdf || !currentPage) return;
    
    async function preloadAdjacentPages() {
      // Preload next page if it exists
      if (currentPage < totalPages && !pageUrls[currentPage + 1]) {
        await renderPageToCache(pdf, currentPage + 1, pageUrls);
        setPageUrls({...pageUrls});
      }
      
      // Preload previous page if it exists
      if (currentPage > 1 && !pageUrls[currentPage - 1]) {
        await renderPageToCache(pdf, currentPage - 1, pageUrls);
        setPageUrls({...pageUrls});
      }
    }
    
    preloadAdjacentPages();
  }, [currentPage, pdf, pageUrls, totalPages]);

  // Clean up and reset state when path changes
  useEffect(() => {
    // Reset state when path changes
    setCurrentPage(1);
    setPageUrls({});
    setError(null);
    setShowPlaceholder(false);
    
    return () => {
      // Clean up any resources when component unmounts
      console.log("PDFViewer cleanup for path:", effectivePath);
    };
  }, [effectivePath]);

  // Simplified render method for reliability
  return (
    <div 
      ref={containerRef}
      className={`pdf-viewer-container ${theme}-theme`}
      style={{ 
        position: 'relative', 
        width: '100%', 
        height: '100%',
        overflow: 'hidden',
        background: theme === 'dark' ? '#2c2c2c' : '#f0f0f0',
        borderRadius: '8px',
        boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
      }}
      {...swipeHandlers}
    >
      {/* Show loading overlay */}
      <AnimatePresence>
        {isLoading && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="pdf-loading-overlay"
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              display: 'flex',
              flexDirection: 'column',
              justifyContent: 'center',
              alignItems: 'center',
              background: theme === 'dark' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.9)',
              zIndex: 10,
              padding: '20px'
            }}
          >
            <div className="loading-spinner" style={{ marginBottom: '20px' }}>
              <div className="spinner"></div>
            </div>
            <h3 style={{ 
              color: theme === 'dark' ? '#fff' : '#333',
              marginBottom: '10px',
              textAlign: 'center'
            }}>
              Loading {bookTitle || 'PDF'}...
            </h3>
            
            <div style={{
              marginTop: '30px',
              padding: '15px',
              background: theme === 'dark' ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.05)',
              borderRadius: '8px',
              maxWidth: '300px',
              textAlign: 'center'
            }}>
              <h4 style={{ marginBottom: '10px', color: theme === 'dark' ? '#ddd' : '#444' }}>
                Touch Controls
              </h4>
              <ul style={{ 
                color: theme === 'dark' ? '#bbb' : '#555',
                textAlign: 'left',
                listStyleType: 'none',
                padding: 0
              }}>
                <li style={{ marginBottom: '5px' }}>• Swipe left/right to turn pages</li>
                <li style={{ marginBottom: '5px' }}>• Pinch to zoom in/out</li>
                <li>• Double tap to reset zoom</li>
              </ul>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      
      {/* Show error message */}
      {error && !isLoading && (
        <div className="pdf-error" style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          textAlign: 'center',
          padding: '20px',
          background: theme === 'dark' ? 'rgba(50,0,0,0.8)' : 'rgba(255,240,240,0.9)',
          border: '1px solid ' + (theme === 'dark' ? '#500' : '#fcc'),
          borderRadius: '8px',
          maxWidth: '80%',
          zIndex: 9
        }}>
          <h3 style={{ color: theme === 'dark' ? '#ff6b6b' : '#d32f2f', marginBottom: '10px' }}>
            Error Loading PDF
          </h3>
          <p style={{ color: theme === 'dark' ? '#ddd' : '#333' }}>{error}</p>
          <p style={{ fontSize: '0.9em', marginTop: '15px', color: theme === 'dark' ? '#aaa' : '#666' }}>
            {effectivePath ? `Path: ${effectivePath.substring(0, 50)}${effectivePath.length > 50 ? '...' : ''}` : 'No path provided'}
          </p>
        </div>
      )}
      
      {/* Show placeholder if no PDF is specified */}
      {showPlaceholder && !isLoading && !error && (
        <div className="pdf-placeholder" style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          textAlign: 'center',
          padding: '20px'
        }}>
          <h3 style={{ color: theme === 'dark' ? '#fff' : '#333' }}>
            No PDF Selected
          </h3>
          <p style={{ color: theme === 'dark' ? '#ddd' : '#666' }}>
            Please select a book to read
          </p>
        </div>
      )}
      
      {/* Show PDF page with animation */}
      <AnimatePresence custom={pageDirection} initial={false}>
        {!isLoading && !error && !showPlaceholder && pageUrls[currentPage] && (
          <motion.div
            key={`page-${currentPage}`}
            className="pdf-page"
            custom={pageDirection}
            variants={pageVariants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{
              x: { type: "spring", stiffness: 300, damping: 30 },
              opacity: { duration: 0.2 }
            }}
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: `translate(-50%, -50%) scale(${scale})`,
              height: 'auto',
              maxHeight: `calc(100% / ${scale})`,
              maxWidth: `calc(100% / ${scale})`,
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              transition: 'transform 0.2s ease-out',
              transformOrigin: 'center center',
              perspective: '1000px'
            }}
            onDoubleClick={() => setScale(1.2)}
          >
            <img 
              src={pageUrls[currentPage]} 
              alt={`Page ${currentPage}`}
              style={{
                boxShadow: '0 5px 15px rgba(0,0,0,0.3)',
                borderRadius: '3px',
                maxHeight: '100%',
                maxWidth: '100%'
              }}
              draggable={false}
            />
          </motion.div>
        )}
      </AnimatePresence>
      
      {/* Page controls */}
      {!isLoading && !error && !showPlaceholder && pdf && (
        <div className="pdf-controls" style={{
          position: 'absolute',
          bottom: '15px',
          left: '0',
          right: '0',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          padding: '5px',
          background: theme === 'dark' ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)',
          borderRadius: '20px',
          margin: '0 auto',
          width: 'fit-content',
          zIndex: 8
        }}>
          <button 
            onClick={() => changePage(-1)} 
            disabled={currentPage <= 1}
            style={{
              background: 'transparent',
              border: 'none',
              cursor: currentPage <= 1 ? 'default' : 'pointer',
              opacity: currentPage <= 1 ? 0.5 : 1,
              color: theme === 'dark' ? '#fff' : '#333',
              padding: '5px 10px',
              fontSize: '20px'
            }}
          >
            ◀
          </button>
          <div style={{
            padding: '0 15px',
            fontSize: '14px',
            color: theme === 'dark' ? '#fff' : '#333'
          }}>
            {currentPage} / {totalPages}
          </div>
          <button 
            onClick={() => changePage(1)} 
            disabled={currentPage >= totalPages}
            style={{
              background: 'transparent',
              border: 'none',
              cursor: currentPage >= totalPages ? 'default' : 'pointer',
              opacity: currentPage >= totalPages ? 0.5 : 1,
              color: theme === 'dark' ? '#fff' : '#333',
              padding: '5px 10px',
              fontSize: '20px'
            }}
          >
            ▶
          </button>
        </div>
      )}
      
      {/* Zoom controls */}
      {!isLoading && !error && !showPlaceholder && pdf && (
        <div className="zoom-controls" style={{
          position: 'absolute',
          top: '15px',
          right: '15px',
          display: 'flex',
          flexDirection: 'column',
          background: theme === 'dark' ? 'rgba(0,0,0,0.5)' : 'rgba(255,255,255,0.7)',
          borderRadius: '20px',
          padding: '5px',
          zIndex: 8
        }}>
          <button 
            onClick={() => changeZoom(0.1)} 
            style={{
              background: 'transparent',
              border: 'none',
              cursor: 'pointer',
              color: theme === 'dark' ? '#fff' : '#333',
              padding: '5px',
              fontSize: '16px'
            }}
          >
            +
          </button>
          <div style={{
            fontSize: '12px',
            textAlign: 'center',
            padding: '2px 0',
            color: theme === 'dark' ? '#ddd' : '#555'
          }}>
            {Math.round(scale * 100)}%
          </div>
          <button 
            onClick={() => changeZoom(-0.1)} 
            style={{
              background: 'transparent',
              border: 'none',
              cursor: 'pointer',
              color: theme === 'dark' ? '#fff' : '#333',
              padding: '5px',
              fontSize: '16px'
            }}
          >
            -
          </button>
        </div>
      )}
      
      {/* Debug button in corner */}
      <button 
        onClick={() => setShowDebug(!showDebug)}
        style={{
          position: 'absolute',
          bottom: '5px',
          right: '5px',
          background: 'transparent',
          border: 'none',
          cursor: 'pointer',
          color: theme === 'dark' ? 'rgba(255,255,255,0.3)' : 'rgba(0,0,0,0.3)',
          padding: '5px',
          fontSize: '12px',
          zIndex: 20
        }}
      >
        •••
      </button>
      
      {/* Debug overlay */}
      {showDebug && (
        <div 
          style={{
            position: 'absolute',
            bottom: '30px',
            right: '5px',
            background: theme === 'dark' ? 'rgba(0,0,0,0.8)' : 'rgba(255,255,255,0.9)',
            border: '1px solid ' + (theme === 'dark' ? '#444' : '#ddd'),
            borderRadius: '5px',
            padding: '10px',
            maxWidth: '300px',
            maxHeight: '200px',
            overflow: 'auto',
            fontSize: '12px',
            color: theme === 'dark' ? '#ddd' : '#333',
            zIndex: 25
          }}
        >
          <h4>Debug Info</h4>
          <p>Path: {effectivePath || 'none'}</p>
          <p>Pages: {currentPage} / {totalPages}</p>
          <p>Scale: {scale.toFixed(2)}</p>
          <p>Cached pages: {Object.keys(pageUrls).length}</p>
          <p>Error: {error || 'none'}</p>
        </div>
      )}
    </div>
  );
};

export default PDFViewer; 